const bars = gsap.utils.toArray(".b");
const h = [190, 280, 360, 470, 710];
const ptr = root.querySelector(".ptr");
const pin = root.querySelector(".pin");
gsap.set(ptr, { drawSVG: "0%" });
gsap.set(pin, { scale: 0, transformOrigin: "50% 50%" });
for (let i = 0; i < bars.length; i++) {
  mt.fromTo(bars[i], { attr: { y: 920, height: 0 } }, { attr: { y: 920 - h[i], height: h[i] }, duration: 1.1, ease: "expo.out", immediateRender: false }, 0.25 + i * 0.11);
}
const a = anchors[beats[0].id].title;
const lift = Math.min(40, Math.max(0, -a.y - a.h));
mt.to(pin, { scale: 1, duration: 0.5, ease: "back.out(2)" }, 1.05);
mt.to(ptr, { drawSVG: "100%", y: -lift, duration: 0.9, ease: "expo.inOut" }, 1.15);
mt.to(bars, { y: -8, duration: Math.max(0.6, D - 2.2), ease: "sine.inOut", stagger: 0.08 }, 1.9);

const cards = gsap.utils.toArray(".card");
const outlines = gsap.utils.toArray(".frame");
gsap.set(cards, { y: -460, rotation: -10, opacity: 0, transformOrigin: "50% 100%" });
gsap.set(outlines, { drawSVG: "0%" });
for (let i = 0; i < cards.length; i++) {
  mt.to(cards[i], { y: 0, rotation: (i - 1) * 7, opacity: 1, duration: 0.95, ease: "expo.out" }, 0.15 + i * 0.13);
  mt.to(outlines[i], { drawSVG: "100%", duration: 0.9, ease: "power2.inOut" }, 0.35 + i * 0.13);
}
mt.to(cards, { y: -14, duration: Math.max(0.8, D - 1.7), ease: "sine.inOut", stagger: 0.12 }, 1.4);

const ring = root.querySelector(".ring");
const core = root.querySelector(".core");
gsap.set([ring, core], { xPercent: -50, yPercent: -50, scale: 0.5, opacity: 0 });
for (let i = 0; i < beats.length; i++) {
  const a = anchors[beats[i].id].title;
  const x = a.x + a.w * 0.62;
  const y = a.y + a.h * 0.5;
  const at = Math.max(0, beats[i].t - 0.15);
  if (i === 0) mt.set([ring, core], { x: x, y: y }, 0);
  mt.to(ring, { x: x, y: y, scale: 1 - (i % 2) * 0.18, opacity: 1, duration: 1.2, ease: "expo.inOut" }, at);
  mt.to(core, { x: x, y: y, scale: 1, opacity: 1, duration: 1.4, ease: "expo.inOut" }, at + 0.06);
}
mt.to(ring, { rotation: 40, duration: D, ease: "none" }, 0);

const level = root.querySelector(".level");
const needle = root.querySelector(".needle");
const shape = root.querySelector(".shape");
const hub = root.querySelector(".hub");
gsap.set(level, { drawSVG: "0% 0%" });
gsap.set(hub, { scale: 0, transformOrigin: "50% 50%" });
mt.to(hub, { scale: 1, duration: 0.5, ease: "back.out(2)" }, 0.2);
mt.to(needle, { morphSVG: shape, duration: 0.9, ease: "expo.inOut" }, 0.35);
mt.fromTo(needle, { rotation: -84, svgOrigin: "450 450" }, { rotation: 48, duration: 1.6, ease: "expo.out", immediateRender: false }, 0.45);
mt.to(level, { drawSVG: "0% 76%", duration: 1.6, ease: "expo.out" }, 0.45);
mt.to(needle, { rotation: 41, duration: Math.max(0.6, D - 2.4), ease: "sine.inOut" }, 2.1);
